add('air-fryer-chicken-breasts','Paprika chicken breasts',C,4,180,5,20,[[4,'each','chicken breasts','Similar size; flatten thick ends to about 2 cm'],[7.5,'ml','canola oil'],[1,'tsp','salt'],[1.5,'tsp','garlic granules'],[1,'tsp','sweet smoked paprika'],[2,'tsp','mixed herbs','', 'dried'],[.5,'tsp','black pepper']],['Combine the salt, herbs and spices. Rub the chicken with oil and coat both sides with the seasoning.','Space the breasts in a single layer. Air fry at 180°C for 18–20 minutes, turning at 10 minutes. Larger breasts may need longer.'],tags=['chicken breast','meal prep'],nutritionNote='Source gives four unweighed breasts and an estimate per breast. Choose similar breasts; actual portion weight and nutrition vary. Rice and greens are excluded.')
add('air-fryer-chicken-nuggets','Panko chicken nuggets',C,4,200,20,12,[[50,'g','plain flour'],[.5,'tsp','garlic powder'],[.5,'tsp','smoked paprika'],[1,'each','egg','Beaten; source allows a second if needed'],[120,'g','panko breadcrumbs'],[600,'g','chicken breast','Cut into even 3 cm pieces']],['Season the flour with garlic and paprika. Put the egg and panko in separate shallow bowls.','Coat chicken first with flour, then egg and finally panko; press gently so the crumbs adhere.','Arrange with gaps in a single layer. Air fry at 200°C for 10–12 minutes, turning halfway. Repeat for any remaining pieces.'],preheat=3,oilFree=True,allergens=['wheat','gluten','egg'],tags=['chicken breast','crispy'],nutritionNote='Publisher estimate uses 600 g chicken divided four ways. Source permits one or two eggs; coating uptake varies. Ketchup is excluded.')
add('air-fryer-chicken-parmigiana','Chicken parmigiana',C,4,180,20,25,[[2,'each','large chicken breasts','Halve horizontally into four cutlets'],[40,'g','plain flour'],[1,'each','egg','Beaten'],[50,'g','panko breadcrumbs'],[25,'g','parmesan','Finely grated'],[60,'ml','tomato pasta sauce'],[125,'g','mozzarella','Cut into four slices']],['Flatten the cutlets to an even 1.5 cm thickness. Set out flour, beaten egg and a mixture of panko and parmesan.','Dust each cutlet with flour, dip in egg and press into the crumb mix. Air fry in one layer at 180°C for 15 minutes, turning once.','Top each with a quarter of the tomato sauce and mozzarella. Return for 5–10 minutes until the cheese melts and browns.'],allergens=['wheat','gluten','egg','milk'],oilFree=True,nutritionNote='Publisher estimate is for one of four cutlets, without spaghetti or serving garnishes. Source allows 60–120 ml tomato sauce; listed recipe uses 60 ml. Breast sizes are unspecified.')
add('air-fryer-chicken-thighs','Crisp bone-in chicken thighs',C,4,180,2,25,[[4,'each','chicken thighs','Bone-in and skin-on'],[1,'tsp','paprika'],[.5,'tsp','mixed herbs','','dried'],[.5,'tsp','garlic granules'],[1,'tsp','olive oil']],['Mix the herbs, paprika and garlic. Rub oil over the thighs and distribute the seasoning on both sides.','Place skin down in a single layer. Cook at 180°C for 10 minutes, turn skin upwards and cook another 10–15 minutes until crisp. Probe beside the bone without touching it.'],nutritionNote='Source reports 111 kcal and 11 g protein per thigh, with no thigh weight specified. This estimate may understate larger supermarket thighs; weigh and recalculate for accurate tracking.')
