add('air-fryer-cheese-ham-toastie','Ham and mustard cheese toastie',Q,1,190,10,10,[[20,'g','butter','Softened'],[2,'each','sourdough bread slices'],[.5,'tsp','English mustard'],[50,'g','mature cheddar','Grated'],[15,'ml','chives','Chopped','fresh'],[1,'each','thick ham slice','','cooked']],['Spread some butter on one side of each bread slice. Mix the remaining butter with mustard, cheese and chives.','Spread the filling on the unbuttered sides and add ham. Close the sandwich with buttered surfaces outwards.','Air fry at 190°C for 10 minutes, turning at 5 minutes. The bread should be crisp and the centre steaming hot.'],preheat=3,allergens=['milk','wheat','gluten'],internal=75,nutritionNote='Publisher estimate assumes its bread and thick ham slice; exact weights are not specified. This is one complete sandwich.')
add('air-fryer-crispy-chilli-beef','Crispy chilli beef and capsicum',M,2,220,15,15,[[250,'g','minute steak','Cut into narrow strips'],[30,'ml','cornflour'],[30,'ml','vegetable oil','Plus a thin brush on the meat'],[2,'each','garlic cloves','Crushed'],[1,'each','ginger piece','Thumb-size, cut into matchsticks'],[1,'each','red chilli','Sliced'],[1,'each','red capsicum','Cut into small chunks'],[4,'each','spring onions','Separate whites and greens'],[60,'ml','rice wine vinegar'],[25,'ml','soy sauce','10 ml for marinade; 15 ml for sauce'],[30,'ml','sweet chilli sauce'],[30,'ml','tomato ketchup'],[.5,'tsp','Chinese five-spice'],[1,'tsp','sesame oil'],[1,'tsp','caster sugar']],['Toss beef with five-spice, 10 ml soy, sesame oil and sugar. Mix in cornflour until the strips have a thin coating, then separate them and brush lightly with oil.','Air fry in a single layer at 220°C for 6 minutes. Turn and cook 4–6 minutes more until crisp. Check the appliance supports this setting.','Heat the measured vegetable oil in a wok. Stir-fry garlic, ginger, chilli, capsicum and onion whites for 2–3 minutes. Add vinegar, remaining soy, sweet chilli sauce and ketchup; simmer for a minute.','Toss the cooked beef through the bubbling sauce for a minute. Scatter with spring onion greens.'],preheat=3,allergens=['soy','wheat','gluten','sesame'],equipment=['Wok or frying pan'],internal=71,nutritionNote='Publisher estimate retained for two portions. It includes 30 ml frying oil plus an unspecified drizzle on the beef; actual oil use changes the estimate.')
